// Generated by AI (UnitTest MCP)
//! Tenant-scoped Administration status and bounded claim recovery for Bridge.
//!
//! Snapshots, exports, lifecycle purges, resets, and raw SQL remain unavailable.
//! ADR-0111's existing recovery endpoint is surfaced only for claims the store
//! already proves expired.

use std::{
    sync::Arc,
    time::{SystemTime, UNIX_EPOCH},
};

use ackplane_server::fleet::{FleetStore, RepositoryFreshness};
use axum::{
    extract::{Path, State},
    http::StatusCode,
    response::Html,
    routing::get,
    Json, Router,
};
use serde::Serialize;

const ADMINISTRATION_PAGE: &str = include_str!("../static/administration.html");

/// Dependencies injected by the Bridge entry point when it merges the
/// Administration sub-router into the application.
#[derive(Clone)]
pub struct AdministrationApiState {
    pub fleet: Arc<FleetStore>,
    pub tenant_id: Arc<str>,
}

impl AdministrationApiState {
    pub fn new(fleet: Arc<FleetStore>, tenant_id: Arc<str>) -> Self {
        Self { fleet, tenant_id }
    }
}

/// Builds the isolated Administration status sub-router.
pub fn administration_routes(state: AdministrationApiState) -> Router {
    Router::new()
        .route("/administration", get(administration_page))
        .route(
            "/api/v1/repositories/:repository_id/administration/status",
            get(repository_administration_status),
        )
        .with_state(state)
}

#[derive(Serialize)]
struct AdministrationStatusResponse {
    repository_id: String,
    projection: ProjectionStatus,
    durability: DurabilityStatus,
    capabilities: Vec<AdministrationCapability>,
}

#[derive(Serialize)]
struct ProjectionStatus {
    freshness: &'static str,
    ledger_stream_position: i64,
    projection_stream_position: Option<i64>,
    projection_updated_at_seconds: Option<u64>,
}

#[derive(Serialize)]
struct DurabilityStatus {
    state: &'static str,
    reason: &'static str,
}

#[derive(Debug, PartialEq, Eq, Serialize)]
struct AdministrationCapability {
    operation: &'static str,
    state: &'static str,
    reason: &'static str,
}

async fn administration_page() -> Html<&'static str> {
    Html(ADMINISTRATION_PAGE)
}

async fn repository_administration_status(
    State(state): State<AdministrationApiState>,
    Path(repository_id): Path<String>,
) -> Result<Json<AdministrationStatusResponse>, StatusCode> {
    let detail = state
        .fleet
        .repository(state.tenant_id.as_ref(), &repository_id)
        .await
        .map_err(|error| {
            tracing::error!(%error, "Bridge Administration repository status query failed");
            StatusCode::INTERNAL_SERVER_ERROR
        })?
        .ok_or(StatusCode::NOT_FOUND)?;

    Ok(Json(AdministrationStatusResponse {
        repository_id: detail.repository_id,
        projection: ProjectionStatus {
            freshness: freshness_label(detail.freshness),
            ledger_stream_position: detail.ledger_stream_position,
            projection_stream_position: detail.projection_stream_position,
            projection_updated_at_seconds: unix_seconds(detail.projection_updated_at),
        },
        // The server's `DurabilityProfile` is process-local today. The Bridge
        // must not infer a durable claim from a missing published record.
        durability: DurabilityStatus {
            state: "not_reported",
            reason: "The deployment has not published a tenant-scoped durability report.",
        },
        capabilities: capabilities(),
    }))
}

fn capabilities() -> Vec<AdministrationCapability> {
    vec![
        AdministrationCapability {
            operation: "status_inspection",
            state: "available",
            reason: "Tenant-scoped projection and capability status are readable.",
        },
        AdministrationCapability {
            operation: "snapshot",
            state: "refused",
            reason: "A verified principal and adopted policy are required.",
        },
        AdministrationCapability {
            operation: "export",
            state: "refused",
            reason: "A verified principal, purpose, and redaction policy are required.",
        },
        AdministrationCapability {
            operation: "claim_recovery",
            state: "available",
            reason: "Only an expired claim can be recovered; the next owner and a reason are recorded, and live claims refuse.",
        },
        AdministrationCapability {
            operation: "recovery_inspection",
            state: "unavailable",
            reason: "An identified backup artifact and recovery evidence are required.",
        },
        AdministrationCapability {
            operation: "lifecycle_purge",
            state: "refused",
            reason: "A verified principal, retention basis, and impact plan are required.",
        },
    ]
}

fn freshness_label(freshness: RepositoryFreshness) -> &'static str {
    match freshness {
        RepositoryFreshness::NeverProjected => "never_projected",
        RepositoryFreshness::Lagging => "lagging",
        RepositoryFreshness::Fresh => "fresh",
    }
}

fn unix_seconds(timestamp: Option<SystemTime>) -> Option<u64> {
    timestamp.and_then(|timestamp| {
        timestamp
            .duration_since(UNIX_EPOCH)
            .ok()
            .map(|duration| duration.as_secs())
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn administration_capabilities_refuse_or_withhold_privileged_lifecycle_work() {
        assert_eq!(
            capabilities(),
            vec![
                AdministrationCapability {
                    operation: "status_inspection",
                    state: "available",
                    reason: "Tenant-scoped projection and capability status are readable.",
                },
                AdministrationCapability {
                    operation: "snapshot",
                    state: "refused",
                    reason: "A verified principal and adopted policy are required.",
                },
                AdministrationCapability {
                    operation: "export",
                    state: "refused",
                    reason: "A verified principal, purpose, and redaction policy are required.",
                },
                AdministrationCapability {
                    operation: "claim_recovery",
                    state: "available",
                    reason: "Only an expired claim can be recovered; the next owner and a reason are recorded, and live claims refuse.",
                },
                AdministrationCapability {
                    operation: "recovery_inspection",
                    state: "unavailable",
                    reason: "An identified backup artifact and recovery evidence are required.",
                },
                AdministrationCapability {
                    operation: "lifecycle_purge",
                    state: "refused",
                    reason: "A verified principal, retention basis, and impact plan are required.",
                },
            ]
        );
    }

    #[tokio::test]
    async fn administration_page_hosts_a_status_only_contract() {
        assert_eq!(administration_page().await.0, ADMINISTRATION_PAGE);
        assert!(ADMINISTRATION_PAGE.contains("Administration status"));
        assert!(ADMINISTRATION_PAGE.contains("status.durability.state"));
        assert!(!ADMINISTRATION_PAGE.contains("DROP DATABASE"));
        assert!(!ADMINISTRATION_PAGE.contains("TRUNCATE"));
        assert!(!ADMINISTRATION_PAGE.contains("database credentials"));
    }
}
